<script setup lang="ts">
import { computed } from "vue";

const props = defineProps<{
  id: string;
  name?: string;
  size?: number;
}>();

const kind = computed<"claude" | "codex" | "codebuddy" | "qoder" | "pi" | "omp" | "deepseek" | "acp">(() => {
  const s = `${props.id} ${props.name ?? ""}`.toLowerCase();
  if (s.includes("claude")) return "claude";
  if (s.includes("codebuddy")) return "codebuddy";
  if (s.includes("qoder")) return "qoder";
  if (s.includes("codex") || s.includes("openai") || s.includes("gpt")) return "codex";
  if (s.includes("omp") || s.includes("oh my pi") || s.includes("oh-my-pi")) return "omp";
  if (s === "pi" || /\bpi\b/.test(s)) return "pi";
  if (s.includes("deepseek") || s === "dsh" || /\bdsh\b/.test(s)) return "deepseek";
  return "acp";
});

const px = computed(() => `${props.size ?? 16}px`);

const colorClass = computed(() => {
  switch (kind.value) {
    case "claude":
      return "text-brand-claude";
    case "codex":
    case "pi":
      return "text-ink";
    case "codebuddy":
      return "text-brand-codebuddy";
    case "qoder":
      return "text-brand-qoder";
    case "omp":
      return "text-brand-omp";
    case "deepseek":
      return "text-brand-deepseek";
    default:
      return "text-ink-2";
  }
});
</script>

